'use strict';

// The levels' own herbs: every plant of a pickable kind a level grows, for
// Gathering.herbsWithin / clearHerbs and Area.herbsWithin / clearHerbs / regrowHerbs, which answer
// without a player near the plants.
//
// herbs/<level>.bin.gz is generated by Dev/tools/gathering/build_herbs.py from the game's
// merged-mesh vegetation (the herbs) and a kit sweep of the game's respawn manager (the
// mushrooms): for each kind [u8 kind][u32 count] and count plants of [i32 dx][i32 dy][i32 dz],
// little-endian, in centimetres from the plant before (the first from the origin). Trosecko and
// Kutnohorsko have theirs.
//
// A level's plants are kept in typed arrays (positions in centimetres) and indexed by 64 m cells.
// The server reads its level's file once, at start (Gathering.herbs): Kutnohorsko's 2.4 million
// plants take about 40 MB.

const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');

const CATALOG = path.join(__dirname, 'herbs');
// A level's name, as its file is named.
const LEVEL = /^[a-z0-9_]+$/;
// The side of the cells the plants are kept in, in metres.
const CELL = 64;
// A kind's header and a plant's size in the file, in bytes.
const KIND_HEADER = 5;
const PLANT_SIZE = 12;

class AuthoredHerbs {
  // kinds: each plant's kind; centimetres: x, y, z of each plant, in whole centimetres.
  constructor(kinds = new Uint8Array(0), centimetres = new Int32Array(0)) {
    this.kinds = kinds instanceof Uint8Array ? kinds : Uint8Array.from(kinds);
    this.centimetres =
      centimetres instanceof Int32Array ? centimetres : Int32Array.from(centimetres);
    this.cells = this.index();
  }

  // Plants as [[kind, x, y, z], ...] in metres (tests).
  static of(plants) {
    return new AuthoredHerbs(
      plants.map((plant) => plant[0]),
      plants.flatMap((plant) => plant.slice(1, 4).map((metres) => Math.round(metres * 100))),
    );
  }

  // A level's file, unzipped.
  static decode(buffer) {
    let total = 0;
    for (let offset = 0; offset + KIND_HEADER <= buffer.length; ) {
      const count = buffer.readUInt32LE(offset + 1);
      total += count;
      offset += KIND_HEADER + count * PLANT_SIZE;
    }
    const kinds = new Uint8Array(total);
    const centimetres = new Int32Array(total * 3);
    let plant = 0;
    for (let offset = 0; offset + KIND_HEADER <= buffer.length; ) {
      const kind = buffer.readUInt8(offset);
      const count = buffer.readUInt32LE(offset + 1);
      offset += KIND_HEADER;
      let x = 0;
      let y = 0;
      let z = 0;
      for (let i = 0; i < count && offset + PLANT_SIZE <= buffer.length; i++) {
        x += buffer.readInt32LE(offset);
        y += buffer.readInt32LE(offset + 4);
        z += buffer.readInt32LE(offset + 8);
        offset += PLANT_SIZE;
        kinds[plant] = kind;
        centimetres[3 * plant] = x;
        centimetres[3 * plant + 1] = y;
        centimetres[3 * plant + 2] = z;
        plant++;
      }
    }
    return new AuthoredHerbs(kinds.subarray(0, plant), centimetres.subarray(0, plant * 3));
  }

  // "cx,cy" -> the indices of the plants in that cell.
  index() {
    const counts = new Map();
    const keys = new Array(this.kinds.length);
    for (let i = 0; i < this.kinds.length; i++) {
      const key = this.cellKey(this.centimetres[3 * i] / 100, this.centimetres[3 * i + 1] / 100);
      keys[i] = key;
      counts.set(key, (counts.get(key) ?? 0) + 1);
    }
    const cells = new Map();
    for (const [key, count] of counts) {
      cells.set(key, { list: new Int32Array(count), size: 0 });
    }
    for (let i = 0; i < keys.length; i++) {
      const cell = cells.get(keys[i]);
      cell.list[cell.size] = i;
      cell.size += 1;
    }
    const lists = new Map();
    for (const [key, cell] of cells) {
      lists.set(key, cell.list);
    }
    return lists;
  }

  cellKey(x, y) {
    return `${Math.floor(x / CELL)},${Math.floor(y / CELL)}`;
  }

  get size() {
    return this.kinds.length;
  }

  kindOf(index) {
    return this.kinds[index];
  }

  positionOf(index) {
    return {
      x: this.centimetres[3 * index] / 100,
      y: this.centimetres[3 * index + 1] / 100,
      z: this.centimetres[3 * index + 2] / 100,
    };
  }

  // The plants whose cells meet the box from (minX, minY) to (maxX, maxY), as indices.
  inBox(minX, minY, maxX, maxY) {
    const found = [];
    const fromX = Math.floor(minX / CELL);
    const toX = Math.floor(maxX / CELL);
    const fromY = Math.floor(minY / CELL);
    const toY = Math.floor(maxY / CELL);
    const take = (cell) => {
      for (const index of cell) {
        found.push(index);
      }
    };
    // A box wider than the level walks the level's cells instead of the box's.
    if ((toX - fromX + 1) * (toY - fromY + 1) > this.cells.size) {
      for (const [key, cell] of this.cells) {
        const [cx, cy] = key.split(',').map(Number);
        if (cx >= fromX && cx <= toX && cy >= fromY && cy <= toY) {
          take(cell);
        }
      }
      return found;
    }
    for (let cx = fromX; cx <= toX; cx++) {
      for (let cy = fromY; cy <= toY; cy++) {
        const cell = this.cells.get(`${cx},${cy}`);
        if (cell) {
          take(cell);
        }
      }
    }
    return found;
  }

  // The plants within `radius` of `center` (inclusive, in three dimensions), as indices.
  within(center, radius) {
    const near = this.inBox(
      center.x - radius,
      center.y - radius,
      center.x + radius,
      center.y + radius,
    );
    return near.filter((index) => {
      const dx = this.centimetres[3 * index] / 100 - center.x;
      const dy = this.centimetres[3 * index + 1] / 100 - center.y;
      const dz = this.centimetres[3 * index + 2] / 100 - center.z;
      return Math.hypot(dx, dy, dz) <= radius;
    });
  }
}

// The herbs of one level (none for a level without a file).
function loadAuthoredHerbs(level, folder = CATALOG) {
  if (typeof level !== 'string' || !LEVEL.test(level)) {
    return new AuthoredHerbs();
  }
  const file = path.join(folder, `${level}.bin.gz`);
  if (!fs.existsSync(file)) {
    return new AuthoredHerbs();
  }
  try {
    return AuthoredHerbs.decode(zlib.gunzipSync(fs.readFileSync(file)));
  } catch (error) {
    throw new Error(`The herb catalog of ${level} could not be read: ${error.message}`);
  }
}

module.exports = { AuthoredHerbs, loadAuthoredHerbs, CELL };
